using System;
using System.Collections.Generic;
using System.Globalization;
using System.IO;
using System.Linq;
using System.Text.Json;
using System.Threading.Tasks;
using Comfort.Common;
using EFT;
using SPTushonka.Common.Http;
using UnityEngine;
namespace LocalSpt5Esp;
internal static class CommandoConsole {
 static readonly List<string> history=new(),output=new();static string input="",session="",pendingSession="",dialog="",rendered="";static int historyIndex;static Task<string[]>? pending;static Vector2 scroll;static GUIStyle? console;static float outputWidth=-1,outputHeight;static bool dirty=true,focusInput;
 static IEftSession? Session()=> (Singleton<TarkovApplication>.Instance??Singleton<AbstractApplication>.Instance?.TryCast<TarkovApplication>())?.Session;
 static string SessionKey(){if(!string.IsNullOrWhiteSpace(RequestHandler.SessionId))return RequestHandler.SessionId;var app=Singleton<TarkovApplication>.Instance??Singleton<AbstractApplication>.Instance?.TryCast<TarkovApplication>()??UnityEngine.Object.FindObjectOfType<TarkovApplication>();return app?.Session?.GetPhpSessionId()??"";}
 static async Task<string> Timed(Task<string> request){if(await Task.WhenAny(request,Task.Delay(12000))!=request)throw new TimeoutException("等待服务端超时");return await request;}
 internal static void Initialize(){Plugin.Self.Log.LogInfo("Commando HTTP session ready: "+!string.IsNullOrWhiteSpace(SessionKey()));}
 static string Dialog(){using var config=JsonDocument.Parse(File.ReadAllText(Path.Combine(BepInEx.Paths.GameRootPath,"SPT_Runtime","SPT_Data","configs","core.json")));return config.RootElement.GetProperty("features").GetProperty("chatbotFeatures").GetProperty("ids").GetProperty("commando").GetString()??throw new ArgumentException("Commando 标识未配置。");}
 static JsonElement Data(JsonElement response){if(response.TryGetProperty("err",out var error)&&error.TryGetInt32(out int code)&&code!=0)throw new InvalidOperationException(response.TryGetProperty("errmsg",out var message)?message.GetString():"SPT 拒绝了请求。");return response.TryGetProperty("data",out var data)?data:response;}
 static async Task<List<(string Id,string Text)>> Replies(string id){using var response=JsonDocument.Parse(await Timed(RequestHandler.PostJsonAsync("/client/mail/dialog/view",JsonSerializer.Serialize(new{dialogId=id,type=1,limit=100}))));var data=Data(response.RootElement);var result=new List<(string,string)>();if(data.ValueKind==JsonValueKind.Object&&data.TryGetProperty("messages",out var messages)&&messages.ValueKind==JsonValueKind.Array)foreach(var message in messages.EnumerateArray()){if(!message.TryGetProperty("uid",out var uid)||uid.GetString()!=id)continue;string text=message.TryGetProperty("text",out var body)?body.GetString()??"":"";if(message.TryGetProperty("_id",out var key))result.Add((key.GetString()??"",text));}return result;}
 static async Task<string[]> Relay(string command,string id){var previous=new HashSet<string>((await Replies(id)).Select(message=>message.Id));try{using var sent=JsonDocument.Parse(await Timed(RequestHandler.PostJsonAsync("/client/mail/msg/send",JsonSerializer.Serialize(new{dialogId=id,type=1,text=command,replyTo=""}))));Data(sent.RootElement);}catch(Exception error){return new[]{"发送结果未确认："+error.Message+"。请先查看原生对话后再决定是否重发。"};}
  for(int attempt=0;attempt<6;attempt++){if(attempt>0)await Task.Delay(500);var messages=await Replies(id);var fresh=messages.Where(message=>!previous.Contains(message.Id)).Select(message=>message.Text).ToArray();if(fresh.Length>0)return fresh;}return new[]{"命令已提交，暂未收到文字回复。请查看 Commando 原生对话或相关邮件；模组不会自动重发。"};}
 static void Append(string value){output.Add(value);if(output.Count>200)output.RemoveAt(0);dirty=true;scroll.y=float.MaxValue;}
 static void Submit(){if(pending!=null)return;if(string.IsNullOrWhiteSpace(input)){Append("请输入命令，或点击“填入 help”。");focusInput=true;return;}try{pendingSession=SessionKey();if(pendingSession.Length==0)throw new ArgumentException("尚未读取到登录会话，请先登录角色后重试。");dialog=Dialog();string command=input;history.Add(command);historyIndex=history.Count;Append("> "+command);input="";pending=Relay(command,dialog);focusInput=true;}catch(Exception error){Append("错误："+error.Message);}}
 internal static void Draw(Rect rect){string key=SessionKey();if(key!=session){session=key;output.Clear();history.Clear();historyIndex=0;input="";dirty=true;Append("Commando · 原生命令中继。输入 help 查看当前服务端支持的命令。");}if(pending?.IsCompleted==true){try{var lines=pending.GetAwaiter().GetResult();if(pendingSession==session)foreach(var line in lines)Append(line);}catch(Exception error){if(pendingSession==session)Append("请求失败："+error.Message+"；不会自动重发。");}pending=null;}
  float x=rect.x,y=rect.y,w=rect.width;InterfaceMenu.Label(new Rect(x,y,w-220,30),"Commando",InterfaceMenu.Accent,20);if(InterfaceMenu.Button(new Rect(x+w-200,y,90,30),"填入 help")){input="help";focusInput=true;}if(InterfaceMenu.Button(new Rect(x+w-102,y,102,30),"清空输出")){output.Clear();dirty=true;}y+=42;InterfaceMenu.Paragraph(new Rect(x,y,w,48),pending!=null?"正在等待 SPT 回复；不会自动重复发送。":key.Length==0?"尚未读取到登录会话，请先登录角色。":string.IsNullOrWhiteSpace(input)?"登录会话已就绪。输入命令或点击“填入 help”。":"登录会话已就绪，可以执行命令。",null,12);y+=58;
  var view=new Rect(x,y,w,Math.Max(80,rect.yMax-y-76));InterfaceMenu.Surface(view,new Color(.025f,.03f,.035f,.92f),8);console??=new GUIStyle(GUI.skin.textArea){richText=false,wordWrap=true,fontSize=14};console.normal.textColor=new Color(.74f,.94f,.80f);if(dirty||outputWidth!=w){rendered=string.Join("\n\n",output);outputWidth=w;outputHeight=Math.Max(view.height-12,console.CalcHeight(new GUIContent(rendered),w-38)+12);dirty=false;}scroll=GUI.BeginScrollView(new Rect(view.x+6,view.y+6,view.width-12,view.height-12),scroll,new Rect(0,0,w-32,outputHeight));GUI.TextArea(new Rect(0,0,w-38,outputHeight),rendered,console);GUI.EndScrollView();
  float bottom=rect.yMax-58;GUI.SetNextControlName("LocalCommandoInput");input=InterfaceMenu.Field(new Rect(x,bottom,w-132,34),input);var old=GUI.enabled;GUI.enabled=old&&pending==null;if(InterfaceMenu.Button(new Rect(x+w-120,bottom,120,34),pending!=null?"等待 SPT…":"执行命令"))Submit();GUI.enabled=old;InterfaceMenu.Label(new Rect(x,bottom+38,w,20),"Enter 执行 · ↑↓ 历史记录 · 未收到回复时不会自动重试",null,11);
  if(focusInput){GUI.FocusControl("LocalCommandoInput");focusInput=false;}var ev=Event.current;if(ev.type==EventType.KeyDown&&GUI.GetNameOfFocusedControl()=="LocalCommandoInput"){if(ev.keyCode is KeyCode.Return or KeyCode.KeypadEnter){Submit();ev.Use();}else if(ev.keyCode is KeyCode.UpArrow or KeyCode.DownArrow){historyIndex=Math.Clamp(historyIndex+(ev.keyCode==KeyCode.UpArrow?-1:1),0,history.Count);input=historyIndex<history.Count?history[historyIndex]:"";ev.Use();}}
 }
 internal static void Reset(){pending=null;pendingSession=dialog="";history.Clear();output.Clear();session=input="";dirty=true;console=null;}
}
